/* GENERATED firmware glue for the motor hub — LEAF hub (local ports only).
   Mechanical wiring derived from the IR (§08): router table, hub_on_body,
   command dispatch, the floor init/on_command/control_tick/status plumbing,
   the sense ticks, and the hub_tasks schedule. The user writes ONLY the
   device hooks in mcu/motor.{c,cpp} (prototypes in motor.device.h).
   This header is #include'd by the device file, which the build compiles. */
#if defined(ARDUINO)

#include <Arduino.h>
extern "C" {
#include "frame.h"
#include "scheduler.h"
#include "router.h"
#include "link.h"
#include "floor.h"
#include "wire_contract.h"
#include "motor.device.h" /* the hand-written device hooks */
}

#ifndef MY_NODE
#define MY_NODE 0x05
#endif

/* Optional per-loop telemetry hook (§08). The glue calls motor_post_control() at
   the end of every control_tick. The device file can provide its own by doing
   `#define MOTOR_POST_CONTROL_OVERRIDE` BEFORE including this header (then
   implementing motor_post_control() itself); otherwise this no-op default is used. */
#ifndef MOTOR_POST_CONTROL_OVERRIDE
extern "C" void motor_post_control(void) {}
#endif

/* One floor per floored command port (§05) — born-disarmed, safe at boot. */
static Floor g_floor_motor_target;
static uint16_t g_applied_seq_motor_target = 0;  /* last command seq we handed the floor */
#define FLOOR_WINDOW_MS_MOTOR_TARGET (FLOOR_MISSES_MOTOR_MOTOR_TARGET * CMD_PERIOD_MS_MOTOR_MOTOR_TARGET)

/* Per-status-port seq. */
static uint16_t g_status_seq_motor_status = 0;
/* A command for motor_target: decode the value, hand its seq to the floor
   (the floor watches the seq, not the value), record applied_seq (§05). */
static void on_command_motor_target(const Frame *f) {
  if (f->port != PORT_MOTOR_MOTOR_TARGET) return;
  if (f->payload_len < 4) return;
  float v = be_get_f32(&f->payload[0]);
  floor_on_command(&g_floor_motor_target, f->seq, v);
  g_applied_seq_motor_target = f->seq;
}
/* The drive loop — period 0 so it runs every loop pass, never starved (§08).
   Each floor gates its own port: target while armed, safe action otherwise
   (default safe). Then the optional per-loop device hook (telemetry). */
static void control_tick(uint32_t now_us) {
  uint32_t now_ms = now_us / 1000u;
  motor_motor_target_drive(floor_tick(&g_floor_motor_target, now_ms));
  motor_post_control();
}
/* IN ports are event-driven via on_command; the scheduled cmd tick is a no-op. */
static void motor_target_cmd_tick(uint32_t now_us) { (void)now_us; }
/* Report motor_status's reported truth (§05): the paired floor's applied_seq +
   floored? flag, so the host reads truth instead of inferring it. */
static void motor_status_sample_tick(uint32_t now_us) {
  (void)now_us; /* status omits t_dev, so the tick needs no clock */
  Frame f;
  f.node = MY_NODE;
  f.port = PORT_MOTOR_MOTOR_STATUS;
  f.seq = ++g_status_seq_motor_status;
  f.stamped = PORT_MOTOR_MOTOR_STATUS_STAMPED;
  f.t_dev = 0;

  be_put_u16(&f.payload[0], g_applied_seq_motor_target);
  f.payload[2] = g_floor_motor_target.armed ? 0 : 1; /* floored? = not armed */
  f.payload_len = 3;

  link_send_up(&f);
}

static Router g_router;

static void deliver_local(const Frame *f, void *) {
  if (f->port == PORT_MOTOR_MOTOR_TARGET) on_command_motor_target(f);
}

/* Meaning-blind inbound (§04): decode the body (CRC-clean at the seam), learn
   t_dev-ness per port just-in-time, route by NODE. seq/t_dev never touched. */
extern "C" void hub_on_body(const uint8_t *body, size_t len) {
  if (len < FRAME_HEADER_BASE_SIZE) return;
  Frame f;
  bool stamped = wire_port_stamped(body[0], body[1]); /* per-port t_dev (§04) */
  if (!frame_decode_body(body, len, stamped, &f)) return;
  RouterSinks sinks = {deliver_local, nullptr, nullptr, nullptr}; /* leaf: local only */
  router_route(&g_router, &f, &sinks);
}
extern "C" void hub_setup(void) {
  /* born-disarmed floors first (§05), so the safe output is selected before any drive */
  floor_init(&g_floor_motor_target, FLOOR_WINDOW_MS_MOTOR_TARGET, 0.0f); /* :zero_torque */

  g_router.my_node = MY_NODE;
  for (int i = 0; i < 256; i++) g_router.route_table[i] = LINK_LOCAL; /* leaf: every port is local */

  motor_device_setup(); /* the hand-written hardware bring-up */
}
/* The schedule (§08): one {period_us, tick} row per port from its rate. The
   drive loop runs EVERY loop (period 0) and is prepended here, never starved. */
static Task motor_tasks[] = {
  { 0, 0, control_tick },  /* period 0 → every loop pass */
  { 20000, 0, motor_target_cmd_tick }  /* motor_target @ 50 Hz */,
  { 20000, 0, motor_status_sample_tick }  /* motor_status @ 50 Hz */
};
#define MOTOR_N_TASKS (sizeof(motor_tasks) / sizeof(motor_tasks[0]))

extern "C" Task *hub_tasks(size_t *n_tasks) {
  *n_tasks = MOTOR_N_TASKS;
  return motor_tasks;
}
#endif /* ARDUINO */
